s = reduceRequest(s, { type: "resolve", data: [1, 2] });
if (s.kind !== "success" || s.data.join() !== "1,2") throw new Error("resolve → success with data.");
s = reduceRequest(s, { type: "reject", message: "503" });
if (s.kind !== "error" || s.message !== "503") throw new Error("reject → error with message.");
s = reduceRequest(s, { type: "reset" });
if (s.kind !== "idle") throw new Error("reset → idle.");

